        ).rejects.toThrow(/cannot read the EC2 instance inventory/);
    });

    it('rejects a role that cannot be assumed', async () => {
        await expect(
            SettingsService.resolveScraperRole({ iamRoleArn: `${ACC}/does-not-exist` } as CloudIAM),
        ).rejects.toThrow(/Unable to assume/);
    });

    it('rejects an external-id-required role with the wrong external id', async () => {
        await expect(
            SettingsService.resolveScraperRole({ iamRoleArn: `${ACC}/ext-scraper`, externalId: 'wrong' } as CloudIAM),
